import{Ct as e,rt as t,t as n,tt as r}from"./chunks/framework.D_6UCjGC.js";var i=JSON.parse(`{"title":"The Docs Build That Lost useData","description":"","frontmatter":{"authorship":["ai"]},"headers":[],"relativePath":"developer/story/vitepress-openapi-ssr-usedata.md","filePath":"developer/story/vitepress-openapi-ssr-usedata.md"}`),a={name:`developer/story/vitepress-openapi-ssr-usedata.md`};function o(n,i,a,o,s,c){return e(),r(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1795284828000`},[...i[0]||=[t(`<h1 id="the-docs-build-that-lost-usedata" tabindex="-1">The Docs Build That Lost <code>useData</code> <a class="header-anchor" href="#the-docs-build-that-lost-usedata" aria-label="Permalink to “The Docs Build That Lost useData”">​</a></h1><p><em>How a patch bump of <code>vitepress-openapi</code> broke page rendering in CI, and why the error pointed at VitePress itself.</em></p><p>Written with AI, November 2026. Fixed by bundling <code>vitepress-openapi</code> for SSR in <code>docs/.vitepress/config.mts</code>.</p><hr><h2 id="the-symptom" tabindex="-1">The Symptom <a class="header-anchor" href="#the-symptom" aria-label="Permalink to “The Symptom”">​</a></h2><p>After a Renovate batch, <code>nx run docs:build:production</code> failed in CI. The client and server bundles built fine, then the page-rendering step failed:</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span>✗ rendering pages...</span></span>
<span class="line"><span>SyntaxError: The requested module &#39;vitepress&#39; does not provide an export named &#39;useData&#39;</span></span>
<span class="line"><span>    at loadESMFromCJS (node:internal/modules/cjs/loader)</span></span></code></pre></div><p>Pagefind looked like the cause because <code>vitepress-plugin-pagefind</code> 0.4.26 → 0.4.27 was in the same batch. It wasn&#39;t: that diff only changes scroll handling in <code>CommandList.vue</code>.</p><h2 id="finding-it" tabindex="-1">Finding It <a class="header-anchor" href="#finding-it" aria-label="Permalink to “Finding It”">​</a></h2><p>VitePress deletes <code>.vitepress/.temp</code> (the SSR bundle) when the build fails. We preloaded a small script that made <code>fs.rm</code> skip <code>.temp</code> paths, so the bundle stayed on disk. <code>app.js</code> left only two third-party imports external:</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span>vitepress-mermaid-renderer   → import ok</span></span>
<span class="line"><span>vitepress-openapi/client     → useData is missing</span></span></code></pre></div><p><code>vitepress-openapi</code> had moved from 0.2.9 to 0.2.14 in the same batch. 0.2.13 (&quot;theme: follow VitePress isDark&quot;) added this to the client entry:</p><div class="language-js" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">import</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> {</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> useData </span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">}</span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;"> from</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &#39;vitepress&#39;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">;</span></span></code></pre></div><p>Versions 0.2.9 and 0.2.12 have no <code>vitepress</code> import.</p><h2 id="why-it-breaks" tabindex="-1">Why It Breaks <a class="header-anchor" href="#why-it-breaks" aria-label="Permalink to “Why It Breaks”">​</a></h2><p>While VitePress bundles code for SSR, it points <code>vitepress</code> at its client runtime, which exports <code>useData</code>. Vite keeps third-party packages external during SSR, though, so Node loads <code>vitepress-openapi/client</code> on its own at render time. Node then resolves <code>vitepress</code> through the package&#39;s <code>exports</code> and gets the <strong>node</strong> entry, the config/build API, which has no <code>useData</code>.</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span>bundled code      : &#39;vitepress&#39; → client runtime   ✓ useData</span></span>
<span class="line"><span>external package  : &#39;vitepress&#39; → dist/node/index  ✗ useData</span></span></code></pre></div><h2 id="the-fix" tabindex="-1">The Fix <a class="header-anchor" href="#the-fix" aria-label="Permalink to “The Fix”">​</a></h2><p>Bundle the package so its <code>vitepress</code> import goes through VitePress&#39;s alias:</p><div class="language-ts" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">vite</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">:</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> {</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">  ssr</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">:</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> {</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">    noExternal</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">:</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> [</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">&#39;vitepress-openapi&#39;</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">]</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">,</span></span>
<span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">  },</span></span>
<span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">},</span></span></code></pre></div><p>Pinning 0.2.12 also works, but it blocks future updates.</p><h2 id="takeaways" tabindex="-1">Takeaways <a class="header-anchor" href="#takeaways" aria-label="Permalink to “Takeaways”">​</a></h2><ul><li>A VitePress plugin that imports client APIs (<code>useData</code>, <code>useRoute</code>, …) must be in <code>ssr.noExternal</code>, or it breaks during the SSR render step only.</li><li>When the SSR bundle fails, keep <code>.temp</code> and import each external package in Node to find the one that fails.</li><li>A Renovate batch breaks the build as a group. Check every bumped package, not just the one that looks most likely.</li></ul>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};